import {
	booleanSchema,
	environmentSchema,
	logLevelSchema,
	portSchema,
	setLogLevel,
	validateEnvironment,
} from '@daz-pilot/backend-utils';
import { z } from '@daz-pilot/daz-pilot-backend-api-types';
import dotenv from 'dotenv';

dotenv.config();

export const LOG_LEVEL = logLevelSchema.safeParse(process.env['LOG_LEVEL']).data ?? 'trace';
setLogLevel(LOG_LEVEL);

export const LOG_LEVEL_HTTP = validateEnvironment('LOG_LEVEL_HTTP', logLevelSchema.default(LOG_LEVEL));

// Environment
export const NODE_ENV = validateEnvironment('NODE_ENV', z.enum(['production', 'development']).optional());
export const ENVIRONMENT = validateEnvironment('ENVIRONMENT', environmentSchema);
export const NETWORK_INTERFACE = validateEnvironment('NETWORK_INTERFACE', z.string());
export const PORT = validateEnvironment('PORT', portSchema);
// Port for the worker process' /api/v1/health probe (worker only, no public API).
export const WORKER_PORT = validateEnvironment('WORKER_PORT', portSchema.default(4001));
export const CORE_BACKEND_DOMAIN = validateEnvironment('CORE_BACKEND_DOMAIN', z.string());
export const FRONTEND_DOMAIN = validateEnvironment('FRONTEND_DOMAIN', z.string());
export const SEND_SERVER_ERROR_MESSAGE = validateEnvironment('SEND_SERVER_ERROR_MESSAGE', booleanSchema.default(false));
// Number of reverse proxies in front of the API (0 = exposed directly). Express
// derives `req.ip` from the last N entries of `X-Forwarded-For`, and the auth
// rate limiters bucket on that value: set too low, every client behind the proxy
// shares one bucket; set too high, clients can spoof their address via the
// header and evade the limit entirely.
export const TRUST_PROXY = validateEnvironment('TRUST_PROXY', z.coerce.number().int().min(0).default(0));
// Requests per IP per 15-minute window across all `/auth` routes. Configurable
// because the test suites drive every login of every seeded user through a
// single loopback address and would otherwise rate-limit themselves out.
export const AUTH_RATE_LIMIT_MAX = validateEnvironment(
	'AUTH_RATE_LIMIT_MAX',
	z.coerce.number().int().positive().default(60),
);
export const SECRETS_ENCRYPTION_KEY = validateEnvironment(
	'SECRETS_ENCRYPTION_KEY',
	z.string().refine((v) => Buffer.from(v, 'base64').length === 32, {
		message: 'SECRETS_ENCRYPTION_KEY must be 32 bytes (base64-encoded, e.g. `openssl rand -base64 32`)',
	}),
);

// Database
export const DB_HOST = validateEnvironment('DB_HOST', z.string());
export const DB_PORT = validateEnvironment('DB_PORT', portSchema);
export const DB_USER = validateEnvironment('DB_USER', z.string());
export const DB_NAME = validateEnvironment('DB_NAME', z.string());
export const DB_PASS = validateEnvironment('DB_PASS', z.string());
export const DB_POOL_SIZE = validateEnvironment('DB_POOL_SIZE', z.coerce.number().default(10));
export const DB_SSL = validateEnvironment('DB_SSL', booleanSchema.default(false));
export const DB_DEBUG_SLOW_DB_ACCESS = validateEnvironment('DB_DEBUG_SLOW_DB_ACCESS', z.coerce.number().default(0));
export const DB_MAX_DEADLOCKS = validateEnvironment('DB_MAX_DEADLOCKS', z.coerce.number().default(10));

// ML-Service
export const ML_SERVICE_URL = validateEnvironment('ML_SERVICE_URL', z.url());
export const ML_SERVICE_TIMEOUT_MS = validateEnvironment(
	'ML_SERVICE_TIMEOUT_MS',
	z.coerce.number().positive().default(120_000),
);
// Chunk size for /embed-frames calls during ingest. Smaller chunks keep each
// HTTP request well below ML_SERVICE_TIMEOUT_MS on CPU-only ml-service nodes
// and let pg-boss retry a single chunk on failure rather than the whole
// video. Deterministic Qdrant point IDs (uuid5 from videoId + global frame
// index + aug index) make those retries idempotent.
export const ML_EMBED_CHUNK_SIZE = validateEnvironment(
	'ML_EMBED_CHUNK_SIZE',
	z.coerce.number().int().positive().default(24),
);

// Media storage (local filesystem for Los-06-04, may move to object storage later)
export const MEDIA_STORAGE_DIR = validateEnvironment('MEDIA_STORAGE_DIR', z.string().default('./media'));
export const MEDIA_PUBLIC_PATH = validateEnvironment('MEDIA_PUBLIC_PATH', z.string().default('/media'));
export const MEDIA_URL_SIGNING_KEY = validateEnvironment(
	'MEDIA_URL_SIGNING_KEY',
	z.string().refine((v) => Buffer.from(v, 'base64').length === 32, {
		message: 'MEDIA_URL_SIGNING_KEY must be 32 bytes (base64-encoded, e.g. `openssl rand -base64 32`)',
	}),
);

// JSON body limit for non-multipart endpoints. Multipart uploads stream to disk
// via multer (see `technicalTermSchemas.ts`). 22mb fits a 15mb scan image as a
// base64 data URL plus JSON wrapper; video uploads are unaffected.
export const HTTP_BODY_LIMIT = validateEnvironment('HTTP_BODY_LIMIT', z.string().default('22mb'));

// Frame extraction tuning. The FPS default mirrors the proof-of-concept
// orchestrator (5 fps): with 3 sharpness candidates per kept frame we sample
// at 15 fps and keep the sharpest of every triple. A 4-second video therefore
// yields ~20 training frames per class, which after augmentation (medium x2)
// gives the LinearSVC enough samples to calibrate well.
export const FRAME_EXTRACTION_FPS = validateEnvironment(
	'FRAME_EXTRACTION_FPS',
	z.coerce.number().positive().default(5),
);
export const FRAME_EXTRACTION_CANDIDATES_PER_FRAME = validateEnvironment(
	'FRAME_EXTRACTION_CANDIDATES_PER_FRAME',
	z.coerce.number().int().positive().default(3),
);

// Hard cap on frames kept per video during ingest. Matches the ml-service
// `DEDUP_MAX_POINTS_PER_CLASS` (150): the dedup pass can never retain more than
// that per class anyway, so extracting more only burns CPU. Bounds worst-case
// ingest runtime (a 100 MB / 10-minute video would otherwise embed thousands of
// frames and blow past the pg-boss ingest expiry). The extractor also lowers
// its sampling rate to spread these frames across the whole clip instead of
// truncating to the first N. See H2 in the ML audit.
export const INGEST_MAX_FRAMES_PER_VIDEO = validateEnvironment(
	'INGEST_MAX_FRAMES_PER_VIDEO',
	z.coerce.number().int().positive().default(150),
);

// Email Configuration
export const SMTP_ENABLED = validateEnvironment('SMTP_ENABLED', booleanSchema.default(true));
export const SMTP_HOST = validateEnvironment('SMTP_HOST', z.string());
export const SMTP_PORT = validateEnvironment('SMTP_PORT', portSchema);
export const SMTP_USERNAME = validateEnvironment('SMTP_USERNAME', z.string());
export const SMTP_PASSWORD = validateEnvironment('SMTP_PASSWORD', z.string());
export const SMTP_FROM_EMAIL = validateEnvironment('SMTP_FROM_EMAIL', z.string());
export const SMTP_FROM_NAME = validateEnvironment('SMTP_FROM_NAME', z.string());

// Redirect URI of the mobile app's OIDC flow. Always CORE_BACKEND_DOMAIN +
// /auth/oidc, so it is derived rather than configured twice.
export const OIDC_APP_URL = validateEnvironment(
	'OIDC_APP_URL',
	z.string().default(`${CORE_BACKEND_DOMAIN.replace(/\/+$/, '')}/auth/oidc`),
);

// Only served in the app-link well-known documents (assetlinks.json /
// apple-app-site-association). Empty defaults keep a local stack startable
// without store credentials; production deployments must set them.
export const UPLOAD_KEY_FINGERPRINT = validateEnvironment('UPLOAD_KEY_FINGERPRINT', z.string().default(''));
export const PLAY_APP_SIGNING_FINGERPRINT = validateEnvironment('PLAY_APP_SIGNING_FINGERPRINT', z.string().default(''));
export const APPLE_APP_TEAM_ID = validateEnvironment('APPLE_APP_TEAM_ID', z.string().default(''));

export const SUPER_ADMIN_API_KEY = validateEnvironment('SUPER_ADMIN_API_KEY', z.string().min(64));

// Apple backdoor credentials
export const BACKDOOR_EMAIL_ADDRESS = validateEnvironment('BACKDOOR_EMAIL_ADDRESS', z.email().optional());
export const BACKDOOR_OTP = validateEnvironment(
	'BACKDOOR_OTP',
	z
		.string()
		.regex(/^\d{6}$/)
		.optional(),
);
